-- SPEC §9 data model. IDs are generated by the app (crypto.randomUUID).
CREATE EXTENSION IF NOT EXISTS citext;

CREATE TABLE users (
  id uuid PRIMARY KEY,
  email citext UNIQUE NOT NULL,
  name text,
  role text NOT NULL CHECK (role IN ('admin', 'facilitator')),
  status text NOT NULL DEFAULT 'active',
  created_at timestamptz NOT NULL DEFAULT now(),
  last_login_at timestamptz
);

CREATE TABLE content_versions (
  version text PRIMARY KEY,
  uploaded_by uuid REFERENCES users(id),
  uploaded_at timestamptz NOT NULL DEFAULT now(),
  json jsonb NOT NULL,
  is_active boolean NOT NULL DEFAULT false
);
CREATE UNIQUE INDEX content_versions_one_active ON content_versions (is_active) WHERE is_active;

CREATE TABLE events (
  id uuid PRIMARY KEY,
  code text UNIQUE NOT NULL,
  name text NOT NULL,
  description text,
  location text,
  timezone text,
  facilitator_id uuid REFERENCES users(id),
  state text NOT NULL CHECK (state IN ('draft', 'open', 'closed', 'deleted')),
  starts_at timestamptz,
  ends_at timestamptz,
  link_policy text NOT NULL DEFAULT 'approval' CHECK (link_policy IN ('approval', 'auto')),
  content_version text REFERENCES content_versions(version),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  closed_at timestamptz,
  deleted_at timestamptz
);

CREATE TABLE groups (
  id uuid PRIMARY KEY,
  team_code text UNIQUE NOT NULL,
  owner_token_hash text,
  event_id uuid REFERENCES events(id),
  link_status text CHECK (link_status IN ('pending', 'approved', 'declined')),
  name text,
  country text,
  state text NOT NULL CHECK (state IN ('draft', 'open', 'closed', 'deleted')),
  starts_at timestamptz,
  ends_at timestamptz,
  content_version text REFERENCES content_versions(version),
  worksheet jsonb NOT NULL DEFAULT '{}',
  field_versions jsonb NOT NULL DEFAULT '{}',
  consent text CHECK (consent IN ('private', 'aggregate', 'identified')),
  consent_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  closed_at timestamptz,
  deleted_at timestamptz
);
CREATE INDEX groups_event_id ON groups (event_id);

CREATE TABLE edit_log (
  id bigserial PRIMARY KEY,
  group_id uuid NOT NULL REFERENCES groups(id) ON DELETE CASCADE,
  path text NOT NULL,
  old_value jsonb,
  new_value jsonb,
  display_name text,
  client_id text,
  at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX edit_log_group_at ON edit_log (group_id, at);

CREATE TABLE audit (
  id bigserial PRIMARY KEY,
  actor text,
  action text NOT NULL,
  target_type text,
  target_id uuid,
  detail jsonb,
  at timestamptz NOT NULL DEFAULT now()
);
